// Runtime support for vecDSL programs generated for Qdrant with {{sdk.typescript.package}}. Generated by vecDSL 7. Do not edit.

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { QdrantClient } from "{{sdk.typescript.package}}";
import type { Schemas } from "{{sdk.typescript.package}}";

const PAGE = 256;
const BATCH = 100;
const DIGITS = 6;
const DISTANCES = ["euclidean", "manhattan"];
const DNS_NAMESPACE = "6ba7b810-9dad-11d1-80b4-00c04fd430c8";
const WAIT = 120;
const POLL = 500;
const SNAPSHOTS = "{{snapshots.path}}";
const SNAPSHOT_NAMES = "vecdsl_snapshots";
const VECTOR_NAME_KEYS = ["size", "distance", "multivector_config", "datatype", "modifier"];

type Args = Record<string, any>;
type Layout = {
  name: string;
  key: string;
  key_type: "int" | "text";
  read_consistency?: Schemas["ReadConsistencyType"];
  ordering?: Schemas["WriteOrdering"];
  vectors?: string[];
  integers?: string[];
  limits?: Record<string, { max_items?: number; max_length?: number }>;
  defaults?: Args;
};
type Filter = Schemas["Filter"];
type Point = { id: string | number; score?: number; payload?: Args | null; vector?: unknown };
type Write = { wait: boolean; ordering?: Schemas["WriteOrdering"]; shard_key?: Schemas["ShardKeySelector"] };
type ShardKey = string | string[] | undefined;

export class UnsupportedFeature extends Error {}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

/** The REST client; grpc_port is used by the Java runtime, which speaks gRPC. */
export class Client {
  constructor(readonly qdrant: QdrantClient) {}

  async close(): Promise<void> {}
}

export async function connect(args: { uri: string; api_key?: string; grpc_port?: number; timeout?: number }): Promise<Client> {
  const options: ConstructorParameters<typeof QdrantClient>[0] = { url: args.uri };
  if (args.api_key) {
    options.apiKey = args.api_key;
  }
  if (args.timeout !== undefined) {
    options.timeout = args.timeout * 1000;
  }
  return new Client(new QdrantClient(options));
}

/** Point id of a primary key: UUIDv5 in the DNS namespace of the key's text, as the Weaviate generator derives it. */
export function pointId(key: unknown): string {
  let text: string;
  if (typeof key === "number") {
    if (!Number.isInteger(key)) {
      throw new TypeError(`cannot use ${key} as a Qdrant primary key`);
    }
    text = BigInt(key).toString();
  } else if (typeof key === "bigint" || typeof key === "string") {
    text = String(key);
  } else {
    throw new TypeError(`cannot use ${String(key)} as a Qdrant primary key`);
  }
  const namespace = Buffer.from(DNS_NAMESPACE.replace(/-/g, ""), "hex");
  const hash = createHash("sha1").update(Buffer.concat([namespace, Buffer.from(text, "utf8")])).digest();
  hash[6] = (hash[6] & 0x0f) | 0x50;
  hash[8] = (hash[8] & 0x3f) | 0x80;
  const hex = hash.subarray(0, 16).toString("hex");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/** Result values in one form for every host language: floats rounded, integral floats as integers. */
function value(item: unknown): unknown {
  if (typeof item === "number") {
    if (Number.isInteger(item)) {
      return item;
    }
    const rounded = Number(item.toFixed(DIGITS));
    return Object.is(rounded, -0) ? 0 : rounded;
  }
  if (Array.isArray(item)) {
    return item.map(value);
  }
  if (item !== null && typeof item === "object") {
    return Object.fromEntries(Object.entries(item).map(([key, entry]) => [key, value(entry)]));
  }
  return item;
}

function chunks<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  for (let start = 0; start < items.length; start += size) {
    result.push(items.slice(start, start + size));
  }
  return result;
}

function consistency(layout: Layout): { consistency?: Schemas["ReadConsistencyType"] } {
  return layout.read_consistency === undefined ? {} : { consistency: layout.read_consistency };
}

function write(layout: Layout, wait: boolean, ordering?: Schemas["WriteOrdering"], shardKey?: ShardKey): Write {
  const level = ordering ?? layout.ordering;
  const options: Write = level === undefined ? { wait } : { wait, ordering: level };
  if (shardKey !== undefined) {
    options.shard_key = shardKey;
  }
  return options;
}

/** Shard key selector of a statement's partitions (custom sharding); absent reads every shard. */
function shards(shardKey: ShardKey): { shard_key?: Schemas["ShardKeySelector"] } {
  return shardKey === undefined ? {} : { shard_key: shardKey };
}

async function sleep(ms: number): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, ms));
}

/** Calls ready() until it returns a value other than undefined or false; throws after the timeout. */
async function poll<T>(ready: () => Promise<T | undefined | false>, what: string, timeout = WAIT): Promise<T> {
  const deadline = Date.now() + timeout * 1000;
  for (;;) {
    const result = await ready();
    if (result !== undefined && result !== false) {
      return result as T;
    }
    if (Date.now() > deadline) {
      throw new Error(`${what} did not finish within ${timeout} s`);
    }
    await sleep(POLL);
  }
}

function id(point: Point): string {
  return String(point.id);
}

// ---------------------------------------------------------------- collections

export async function hasCollection(client: Client, args: { name: string }): Promise<boolean> {
  return (await client.qdrant.collectionExists(args.name)).exists;
}

export async function dropCollection(client: Client, args: { name: string }): Promise<void> {
  await client.qdrant.deleteCollection(args.name);
}

export async function createCollection(client: Client, args: {
  name: string;
  vectors?: Record<string, Schemas["VectorParams"]>;
  sparse_vectors?: Record<string, Schemas["SparseVectorParams"]>;
  indexes?: { field: string; schema: Schemas["PayloadSchemaParams"] }[];
  optimizers?: Schemas["OptimizersConfigDiff"];
  strict_mode?: boolean;
  metadata?: Args;
  aliases?: string[];
  replication_factor?: number;
  shard_number?: number;
  payload?: Schemas["PayloadStorageParams"];
  sharding_method?: Schemas["ShardingMethod"];
  shard_keys?: string[];
}): Promise<void> {
  const options: Schemas["CreateCollection"] = { vectors: args.vectors ?? {} };
  if (args.replication_factor !== undefined) {
    options.replication_factor = args.replication_factor;
  }
  if (args.shard_number !== undefined) {
    options.shard_number = args.shard_number;
  }
  if (args.sharding_method !== undefined) {
    options.sharding_method = args.sharding_method;
  }
  if (args.payload !== undefined) {
    options.payload = args.payload;
  }
  if (args.sparse_vectors !== undefined) {
    options.sparse_vectors = args.sparse_vectors;
  }
  if (args.optimizers !== undefined) {
    options.optimizers_config = args.optimizers;
  }
  if (args.strict_mode !== undefined) {
    options.strict_mode_config = { enabled: args.strict_mode };
  }
  if (args.metadata !== undefined) {
    options.metadata = args.metadata;
  }
  await client.qdrant.createCollection(args.name, options);
  for (const shardKey of args.shard_keys ?? []) {
    await createShardKey(client, { name: args.name, shard_key: shardKey });
  }
  for (const index of args.indexes ?? []) {
    await client.qdrant.createPayloadIndex(args.name, { field_name: index.field, field_schema: index.schema, wait: true });
  }
  if (args.aliases !== undefined && args.aliases.length > 0) {
    await client.qdrant.updateCollectionAliases({
      actions: args.aliases.map((alias) => ({ create_alias: { collection_name: args.name, alias_name: alias } })),
    });
  }
}

export async function createPayloadIndex(client: Client, args: { name: string; field: string; schema: Schemas["PayloadSchemaParams"] }): Promise<void> {
  await client.qdrant.createPayloadIndex(args.name, { field_name: args.field, field_schema: args.schema, wait: true });
}

export async function createAlias(client: Client, args: { alias: string; collection: string }): Promise<void> {
  await client.qdrant.updateCollectionAliases({ actions: [{ create_alias: { collection_name: args.collection, alias_name: args.alias } }] });
}

/** Points an alias at another collection in one request: delete and create are applied together. */
export async function swapAlias(client: Client, args: { alias: string; collection: string }): Promise<void> {
  await client.qdrant.updateCollectionAliases({
    actions: [{ delete_alias: { alias_name: args.alias } }, { create_alias: { collection_name: args.collection, alias_name: args.alias } }],
  });
}

// ---------------------------------------------------------------- writes

function check(layout: Layout, record: Args): void {
  for (const [field, limit] of Object.entries(layout.limits ?? {})) {
    const item = record[field];
    if (item === undefined || item === null) {
      continue;
    }
    if (limit.max_items !== undefined && item.length > limit.max_items) {
      throw new RangeError(`${field} has ${item.length} items; at most ${limit.max_items} are allowed`);
    }
    if (limit.max_length !== undefined) {
      for (const text of Array.isArray(item) ? item : [item]) {
        if (typeof text === "string" && text.length > limit.max_length) {
          throw new RangeError(`${field} is longer than ${limit.max_length} characters`);
        }
      }
    }
  }
}

function vectorOf(item: any): Schemas["Vector"] {
  if (!Array.isArray(item)) {
    return { indices: item.indices.map(Number), values: item.values.map(Number) };
  }
  return item.map((x: unknown) => (Array.isArray(x) ? x.map(Number) : Number(x))) as Schemas["Vector"];
}

/** Payload and named vectors of a record; absent and null are the same. JavaScript numbers carry no int/float distinction. */
function split(layout: Layout, record: Args): { payload: Args; named: Record<string, Schemas["Vector"]> } {
  check(layout, record);
  const vectors = new Set(layout.vectors ?? []);
  const payload: Args = {};
  const named: Record<string, Schemas["Vector"]> = {};
  for (const [name, item] of Object.entries(record)) {
    if (item === null || item === undefined) {
      continue;
    }
    if (vectors.has(name)) {
      named[name] = vectorOf(item);
    } else {
      payload[name] = item;
    }
  }
  return { payload, named };
}

/** A point of a record; slice holds the tenant and namespace payload values of the write. */
function pointOf(layout: Layout, row: Args, slice?: Args): Schemas["PointStruct"] {
  const record = { ...(layout.defaults ?? {}), ...row, ...(slice ?? {}) };
  const key = record[layout.key];
  if (key === undefined || key === null) {
    throw new Error(`record without primary key ${layout.key}: ${JSON.stringify(row)}`);
  }
  const { payload, named } = split(layout, record);
  return { id: pointId(key), vector: named, payload };
}

function filterOf(where: Args | undefined): Filter | undefined {
  return where === undefined ? undefined : (where as Filter);
}

async function existing(client: Client, layout: Layout, ids: string[], shardKey?: ShardKey): Promise<Set<string>> {
  const found = new Set<string>();
  for (const chunk of chunks(ids, PAGE)) {
    const records = await client.qdrant.retrieve(layout.name, {
      ids: chunk, with_payload: false, with_vector: false, ...consistency(layout), ...shards(shardKey),
    });
    records.forEach((record) => found.add(id(record)));
  }
  return found;
}

/** Every point that matches a filter, through paginated scrolls; a repeated page offset ends the scroll. */
async function pages(client: Client, layout: Layout, where: Args | undefined, payload: Schemas["WithPayloadInterface"],
  vectors: Schemas["WithVector"], shardKey?: ShardKey): Promise<Point[]> {
  const found: Point[] = [];
  const seen = new Set<string>();
  let offset: Schemas["ExtendedPointId"] | null | undefined = undefined;
  for (;;) {
    const page: Schemas["ScrollResult"] = await client.qdrant.scroll(layout.name, {
      filter: filterOf(where), limit: PAGE, offset, with_payload: payload, with_vector: vectors, ...consistency(layout),
      ...shards(shardKey),
    });
    found.push(...(page.points as Point[]));
    offset = page.next_page_offset as Schemas["ExtendedPointId"] | null | undefined;
    if (offset === null || offset === undefined || seen.has(String(offset))) {
      return found;
    }
    seen.add(String(offset));
  }
}

/** Ids of every point that matches a filter. */
async function matching(client: Client, layout: Layout, where: Args | undefined, shardKey?: ShardKey): Promise<string[]> {
  return (await pages(client, layout, where, false, false, shardKey)).map(id);
}

async function targets(client: Client, layout: Layout, ids: unknown[] | undefined, where: Args | undefined, shardKey?: ShardKey): Promise<string[]> {
  if (ids !== undefined && ids.length > 0) {
    const wanted = [...new Set(ids.map(pointId))];
    if (where !== undefined) {
      const selected = new Set(await matching(client, layout, { must: [{ has_id: wanted }, where] }, shardKey));
      return wanted.filter((pid) => selected.has(pid));
    }
    const found = await existing(client, layout, wanted, shardKey);
    return wanted.filter((pid) => found.has(pid));
  }
  if (where !== undefined) {
    return matching(client, layout, where, shardKey);
  }
  throw new Error("the statement selects no records");
}

async function upsert(client: Client, layout: Layout, points: Schemas["PointStruct"][], batchSize: number, options: Write,
  mode?: Schemas["UpdateMode"]): Promise<void> {
  for (const chunk of chunks(points, batchSize)) {
    await client.qdrant.upsert(layout.name, { points: chunk, ...options, ...(mode === undefined ? {} : { update_mode: mode }) });
  }
}

export async function insertRows(client: Client, args: { collection: Layout; rows: Args[]; on_conflict?: string; batch_size?: number;
  wait?: boolean; ordering?: Schemas["WriteOrdering"]; slice?: Args; shard_key?: ShardKey }): Promise<Args> {
  const layout = args.collection;
  const points = args.rows.map((row) => pointOf(layout, row, args.slice));
  const found = await existing(client, layout, points.map((point) => String(point.id)));
  if (found.size > 0 && (args.on_conflict ?? "error") === "error") {
    throw new Error(`${found.size} records already exist in ${layout.name}`);
  }
  const fresh = points.filter((point) => !found.has(String(point.id)));
  await upsert(client, layout, fresh, args.batch_size ?? BATCH, write(layout, args.wait ?? false, args.ordering, args.shard_key), "insert_only");
  return { insert_count: fresh.length, skipped: points.length - fresh.length };
}

export async function upsertRows(client: Client, args: { collection: Layout; rows: Args[]; batch_size?: number; wait?: boolean;
  ordering?: Schemas["WriteOrdering"]; slice?: Args; shard_key?: ShardKey }): Promise<Args> {
  const layout = args.collection;
  const points = args.rows.map((row) => pointOf(layout, row, args.slice));
  await upsert(client, layout, points, args.batch_size ?? BATCH, write(layout, args.wait ?? false, args.ordering, args.shard_key));
  return { upsert_count: points.length };
}

/** array-append and array-remove: each target's stored array with the items appended or removed, written back. */
async function arrays(client: Client, layout: Layout, selected: string[], items: Args, append: string[], removeItems: string[],
  options: Write): Promise<void> {
  const fields = [...append, ...removeItems];
  for (const chunk of chunks(selected, PAGE)) {
    const stored = await client.qdrant.retrieve(layout.name, { ids: chunk, with_payload: fields, with_vector: false });
    for (const point of stored) {
      const payload = point.payload ?? {};
      const changed: Args = {};
      for (const field of append) {
        changed[field] = [...((payload[field] as unknown[] | undefined) ?? []), ...((items[field] as unknown[] | undefined) ?? [])];
      }
      for (const field of removeItems) {
        const dropped = (items[field] as unknown[] | undefined) ?? [];
        changed[field] = ((payload[field] as unknown[] | undefined) ?? []).filter((x) => !dropped.some((y) => y === x));
      }
      check(layout, changed);
      await client.qdrant.setPayload(layout.name, { payload: changed, points: [point.id], ...options });
    }
  }
}

export async function updateRows(client: Client, args: { collection: Layout; ids?: unknown[]; filter?: Args; values?: Args; rows?: Args[];
  remove?: string[]; mode?: string; wait?: boolean; ordering?: Schemas["WriteOrdering"]; shard_key?: ShardKey; append?: string[];
  remove_items?: string[] }): Promise<Args> {
  const layout = args.collection;
  const name = layout.name;
  const replacements = new Map<string, Args>((args.rows ?? []).map((row) => [pointId(row[layout.key]), row]));
  let selected: string[];
  if (replacements.size > 0) {
    const chosen = new Set((args.ids ?? []).map(pointId));
    selected = (await targets(client, layout, (args.rows ?? []).map((row) => row[layout.key]), args.filter, args.shard_key))
      .filter((pid) => chosen.size === 0 || chosen.has(pid));
  } else if ((args.ids !== undefined && args.ids.length > 0) || args.filter !== undefined) {
    selected = await targets(client, layout, args.ids, args.filter, args.shard_key);
  } else {
    throw new Error("update requires ids, a filter or records");
  }
  const options = write(layout, args.wait ?? false, args.ordering, args.shard_key);
  const mode = args.mode ?? "merge";
  if (replacements.size === 0 && mode !== "replace") {
    const append = args.append ?? [];
    const removeItems = args.remove_items ?? [];
    const listed = new Set([...append, ...removeItems]);
    const items: Args = {};
    const plain: Args = {};
    for (const [field, item] of Object.entries(args.values ?? {})) {
      if (listed.has(field)) {
        items[field] = item;
      } else {
        plain[field] = item;
      }
    }
    const { payload, named } = split(layout, plain);
    if (layout.key in payload) {
      throw new Error(`update cannot change the primary key ${layout.key}`);
    }
    if (Object.keys(payload).length > 0 && selected.length > 0) {
      await client.qdrant.setPayload(name, { payload, points: selected, ...options });
    }
    if (Object.keys(named).length > 0 && selected.length > 0) {
      await client.qdrant.updateVectors(name, { points: selected.map((pid) => ({ id: pid, vector: named })), ...options });
    }
    if (args.remove !== undefined && args.remove.length > 0 && selected.length > 0) {
      await client.qdrant.deletePayload(name, { keys: args.remove, points: selected, ...options });
    }
    if (listed.size > 0 && selected.length > 0) {
      await arrays(client, layout, selected, items, append, removeItems, options);
    }
    return { update_count: selected.length };
  }
  for (const pid of selected) {
    const record = { ...(replacements.get(pid) ?? {}), ...(args.values ?? {}) };
    const key = record[layout.key];
    if (key !== undefined && key !== null && pointId(key) !== pid) {
      throw new Error(`update cannot change the primary key ${layout.key}`);
    }
    const { payload, named } = split(layout, record);
    if (mode === "replace") {
      if (!(layout.key in payload)) {
        const stored = await client.qdrant.retrieve(name, { ids: [pid], with_payload: [layout.key], with_vector: false });
        payload[layout.key] = stored[0].payload?.[layout.key];
      }
      await client.qdrant.overwritePayload(name, { payload, points: [pid], ...options });
    } else if (Object.keys(payload).length > 0) {
      await client.qdrant.setPayload(name, { payload, points: [pid], ...options });
    }
    if (Object.keys(named).length > 0) {
      await client.qdrant.updateVectors(name, { points: [{ id: pid, vector: named }], ...options });
    }
    if (args.remove !== undefined && args.remove.length > 0) {
      await client.qdrant.deletePayload(name, { keys: args.remove, points: [pid], ...options });
    }
  }
  return { update_count: selected.length };
}

/** The first targets in primary key order. */
async function first(client: Client, layout: Layout, selected: string[], limit: number): Promise<string[]> {
  const keyed: [unknown, string][] = [];
  for (const chunk of chunks(selected, PAGE)) {
    const stored = await client.qdrant.retrieve(layout.name, { ids: chunk, with_payload: [layout.key], with_vector: false });
    stored.forEach((point) => keyed.push([point.payload?.[layout.key], id(point as Point)]));
  }
  keyed.sort(([a], [b]) => compare(a, b));
  return keyed.slice(0, limit).map(([, pid]) => pid);
}

function compare(a: unknown, b: unknown): number {
  return (a as number) < (b as number) ? -1 : (a as number) > (b as number) ? 1 : 0;
}

export async function deleteRows(client: Client, args: { collection: Layout; ids?: unknown[]; filter?: Args; delete_all?: boolean;
  wait?: boolean; ordering?: Schemas["WriteOrdering"]; shard_key?: ShardKey; limit?: number }): Promise<Args> {
  const layout = args.collection;
  const options = write(layout, args.wait ?? false, args.ordering, args.shard_key);
  if (args.delete_all && args.limit === undefined) {
    const total = await count(client, { collection: layout, filter: args.filter, shard_key: args.shard_key });
    await client.qdrant.delete(layout.name, { filter: filterOf(args.filter) ?? {}, ...options });
    return { delete_count: total };
  }
  const every = args.limit !== undefined && (args.ids === undefined || args.ids.length === 0) && args.filter === undefined;
  let selected = await targets(client, layout, args.ids, every ? {} : args.filter, args.shard_key);
  if (args.limit !== undefined) {
    selected = await first(client, layout, selected, args.limit);
  }
  for (const chunk of chunks(selected, PAGE)) {
    await client.qdrant.delete(layout.name, { points: chunk, ...options });
  }
  return { delete_count: selected.length };
}

// ---------------------------------------------------------------- reads

function payloadOf(layout: Layout, output: string[]): string[] {
  return [...new Set([layout.key, ...output])];
}

function withVectors(vectors: string[] | undefined): string[] | false {
  return vectors !== undefined && vectors.length > 0 ? vectors : false;
}

function rowOf(layout: Layout, point: Point, output: string[], vectors: string[] | undefined): Args {
  const payload = point.payload ?? {};
  const row: Args = { [layout.key]: payload[layout.key] };
  for (const name of output) {
    row[name] = value(payload[name] ?? null);
  }
  const stored = (point.vector !== null && typeof point.vector === "object" && !Array.isArray(point.vector) ? point.vector : {}) as Args;
  for (const name of vectors ?? []) {
    row[name] = value(stored[name] ?? null);
  }
  return row;
}

/** Records by primary key; a tenant or namespace filter restricts them to its slice. */
export async function getRows(client: Client, args: { collection: Layout; ids: unknown[]; output: string[]; vectors?: string[];
  filter?: Args; shard_key?: ShardKey }): Promise<Args[]> {
  const layout = args.collection;
  const wanted = [...new Set(args.ids.map(pointId))];
  const records: Point[] = args.filter !== undefined
    ? await pages(client, layout, { must: [{ has_id: wanted }, args.filter] }, payloadOf(layout, args.output), withVectors(args.vectors),
      args.shard_key)
    : (await client.qdrant.retrieve(layout.name, {
      ids: wanted, with_payload: payloadOf(layout, args.output), with_vector: withVectors(args.vectors), ...consistency(layout),
      ...shards(args.shard_key),
    })) as Point[];
  const found = new Map(records.map((record) => [id(record), record as Point]));
  return wanted.filter((pid) => found.has(pid)).map((pid) => rowOf(layout, found.get(pid)!, args.output, args.vectors));
}

export async function count(client: Client, args: { collection: Layout; filter?: Args; shard_key?: ShardKey }): Promise<number> {
  return (await client.qdrant.count(args.collection.name, { filter: filterOf(args.filter), exact: true, ...shards(args.shard_key) })).count;
}

/** Records in the order of an indexed payload field (the integer key by default), else sorted by key in the runtime. */
export async function scroll(client: Client, args: { collection: Layout; output: string[]; filter?: Args; limit?: number; offset?: number;
  vectors?: string[]; order?: Schemas["OrderBy"]; shard_key?: ShardKey }): Promise<Args[]> {
  const layout = args.collection;
  const skip = args.offset ?? 0;
  let selected: Point[] = [];
  if (args.order !== undefined) {
    const size = args.limit === undefined ? await count(client, { collection: layout, filter: args.filter, shard_key: args.shard_key }) : skip + args.limit;
    if (size === 0) {
      return [];
    }
    const page = await client.qdrant.scroll(layout.name, {
      filter: filterOf(args.filter), limit: size, order_by: args.order, with_payload: payloadOf(layout, args.output),
      with_vector: withVectors(args.vectors), ...consistency(layout), ...shards(args.shard_key),
    });
    selected = (page.points as Point[]).slice(skip);
  } else {
    selected = await pages(client, layout, args.filter, payloadOf(layout, args.output), withVectors(args.vectors), args.shard_key);
    const key = (point: Point) => point.payload?.[layout.key];
    selected = selected.sort((a, b) => (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0)).slice(skip);
  }
  if (args.limit !== undefined) {
    selected = selected.slice(0, args.limit);
  }
  return selected.map((point) => rowOf(layout, point, args.output, args.vectors));
}

/** Canonical similarity of a Qdrant score; Euclid and Manhattan scores are distances. */
export function similarity(metric: string, score: number): number {
  return DISTANCES.includes(metric) ? -score : score;
}

/** Qdrant's score_threshold for a lower similarity bound: an upper distance bound for Euclid and Manhattan. */
function threshold(metric: string, scoreMin: number | undefined): number | undefined {
  if (scoreMin === undefined) {
    return undefined;
  }
  return DISTANCES.includes(metric) ? -scoreMin : scoreMin;
}

function within(score: number, scoreMin: number | undefined, scoreMax: number | undefined): boolean {
  return (scoreMin === undefined || score >= scoreMin) && (scoreMax === undefined || score <= scoreMax);
}

function hits(layout: Layout, points: Point[], scores: number[], output: string[], vectors: string[] | undefined,
  scoreMin: number | undefined, scoreMax: number | undefined): Args[] {
  const result: Args[] = [];
  points.forEach((point, index) => {
    const score = scores[index];
    if (within(score, scoreMin, scoreMax)) {
      const row = rowOf(layout, point, output, vectors);
      const key = row[layout.key];
      delete row[layout.key];
      result.push({ id: key, score: value(score), ...row });
    }
  });
  return result;
}

type Search = {
  collection: Layout;
  limit: number;
  output: string[];
  filter?: Args;
  offset?: number;
  score_min?: number;
  score_max?: number;
  native?: boolean;
  vectors?: string[];
  params?: Schemas["SearchParams"];
  shard_key?: ShardKey;
};

function request(args: Search): Schemas["QueryRequest"] & { consistency?: Schemas["ReadConsistencyType"] } {
  const result: Schemas["QueryRequest"] & { consistency?: Schemas["ReadConsistencyType"] } = {
    limit: args.limit, with_payload: payloadOf(args.collection, args.output), with_vector: withVectors(args.vectors),
    ...consistency(args.collection), ...shards(args.shard_key),
  };
  if (args.filter !== undefined) {
    result.filter = filterOf(args.filter);
  }
  if (args.offset !== undefined) {
    result.offset = args.offset;
  }
  if (args.params !== undefined) {
    result.params = args.params;
  }
  return result;
}

function scored(args: Search, metric: string | undefined, points: Point[]): Args[] {
  const scores = points.map((point) => (metric === undefined || args.native ? Number(point.score) : similarity(metric, Number(point.score))));
  return hits(args.collection, points, scores, args.output, args.vectors, args.score_min, args.score_max);
}

export async function vectorSearch(client: Client, args: Search & { field: string; vector: unknown; metric: string;
  mmr?: Schemas["Mmr"]; prefetch?: Args[]; group_by?: string; group_size?: number }): Promise<Args[]> {
  const nearest = vectorOf(args.vector);
  const query: Schemas["QueryInterface"] = args.mmr === undefined ? nearest : { nearest, mmr: args.mmr };
  const body = { ...request(args), query, using: args.field };
  const limit = args.native ? undefined : threshold(args.metric, args.score_min);
  if (limit !== undefined) {
    body.score_threshold = limit;
  }
  if (args.prefetch !== undefined) {
    body.prefetch = args.prefetch as Schemas["Prefetch"][];
  }
  if (args.group_by !== undefined) {
    const { offset: _offset, ...grouped } = body;
    const response = await client.qdrant.queryGroups(args.collection.name, {
      ...grouped, group_by: args.group_by, ...(args.group_size === undefined ? {} : { group_size: args.group_size }),
    });
    return response.groups.map((group) => ({ group: value(group.id), hits: scored(args, args.metric, group.hits as Point[]) }));
  }
  const response = await client.qdrant.query(args.collection.name, body);
  return scored(args, args.metric, response.points as Point[]);
}

function textQuery(query: string, bm25: Schemas["Bm25Params"] | undefined): Schemas["TextQuery"] {
  return bm25 === undefined ? { text: query } : { text: { query, scoring: { bm25 } } };
}

export async function keywordSearch(client: Client, args: Search & { query: string; field: string; bm25?: Schemas["Bm25Params"] }): Promise<Args[]> {
  const body = { ...request(args), query: textQuery(args.query, args.bm25), using: args.field };
  if (args.score_min !== undefined) {
    body.score_threshold = args.score_min;
  }
  const response = await client.qdrant.query(args.collection.name, body);
  return scored(args, undefined, response.points as Point[]);
}

type Leg = {
  kind: "vector" | "keyword";
  field: string;
  limit?: number;
  vector?: unknown;
  metric?: string;
  query?: string;
  bm25?: Schemas["Bm25Params"];
  filter?: Args;
  params?: Schemas["SearchParams"];
  score_min?: number;
  score_max?: number;
  weight?: number;
};

/** One hybrid leg as a Qdrant query request: a nearest-vector or a BM25 text query with its own filter and limit. */
function legQuery(leg: Leg, limit: number): Schemas["Prefetch"] {
  const result: Schemas["Prefetch"] = { using: leg.field, limit };
  if (leg.kind === "vector") {
    result.query = vectorOf(leg.vector);
    const bound = threshold(leg.metric!, leg.score_min);
    if (bound !== undefined) {
      result.score_threshold = bound;
    }
    if (leg.params !== undefined) {
      result.params = leg.params;
    }
  } else {
    result.query = textQuery(leg.query!, leg.bm25);
  }
  if (leg.filter !== undefined) {
    result.filter = filterOf(leg.filter);
  }
  return result;
}

function fused(fusion: string, weight: number, ranked: [string, number][]): Map<string, number> {
  if (fusion === "weighted") {
    return new Map(ranked.map(([pid, score]) => [pid, weight * score]));
  }
  const scores = ranked.map(([, score]) => score);
  const low = scores.length > 0 ? Math.min(...scores) : 0;
  const high = scores.length > 0 ? Math.max(...scores) : 0;
  return new Map(ranked.map(([pid, score]) => [pid, weight * (high > low ? (score - low) / (high - low) : 1)]));
}

/** rrf fuses on the server; weighted and relative_score fuse one batched request per leg in the runtime. */
export async function hybridSearch(client: Client, args: { collection: Layout; legs: Leg[]; limit: number; fusion: string; output: string[];
  k?: number; offset?: number; score_min?: number; score_max?: number; vectors?: string[]; shard_key?: ShardKey }): Promise<Args[]> {
  const layout = args.collection;
  const sized = args.legs.map((leg) => ({ leg, limit: leg.limit ?? args.limit + (args.offset ?? 0) }));
  const payload = payloadOf(layout, args.output);
  if (args.fusion === "rrf") {
    const body: Schemas["QueryRequest"] = {
      prefetch: sized.map(({ leg, limit }) => legQuery(leg, limit)), query: { rrf: { k: (args.k ?? 60) + 1 } }, limit: args.limit,
      with_payload: payload, with_vector: withVectors(args.vectors),
    };
    if (args.offset !== undefined) {
      body.offset = args.offset;
    }
    const response = await client.qdrant.query(layout.name, { ...body, ...consistency(layout), ...shards(args.shard_key) });
    const points = response.points as Point[];
    return hits(layout, points, points.map((point) => Number(point.score)), args.output, args.vectors, args.score_min, args.score_max);
  }
  const searches = sized.map(({ leg, limit }) => ({
    ...legQuery(leg, limit), with_payload: payload, with_vector: withVectors(args.vectors), ...shards(args.shard_key),
  }));
  const responses = await client.qdrant.queryBatch(layout.name, { searches, ...consistency(layout) });
  const totals = new Map<string, number>();
  const found = new Map<string, Point>();
  sized.forEach(({ leg }, index) => {
    const ranked: [string, number][] = [];
    for (const point of responses[index].points as Point[]) {
      const score = leg.kind === "vector" ? similarity(leg.metric!, Number(point.score)) : Number(point.score);
      if (leg.kind === "vector" && !within(score, leg.score_min, leg.score_max)) {
        continue;
      }
      if (!found.has(id(point))) {
        found.set(id(point), point);
      }
      ranked.push([id(point), score]);
    }
    for (const [pid, part] of fused(args.fusion, leg.weight ?? 1, ranked)) {
      totals.set(pid, (totals.get(pid) ?? 0) + part);
    }
  });
  const key = (pid: string) => found.get(pid)!.payload?.[layout.key];
  const ranking = [...totals.keys()].sort((a, b) => totals.get(b)! - totals.get(a)! || (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0));
  const page = ranking.slice(args.offset ?? 0, (args.offset ?? 0) + args.limit);
  return hits(layout, page.map((pid) => found.get(pid)!), page.map((pid) => totals.get(pid)!), args.output, args.vectors,
    args.score_min, args.score_max);
}

function example(item: unknown): Schemas["VectorInput"] {
  return Array.isArray(item) ? vectorOf(item) : pointId(item);
}

/** Qdrant's average_vector strategy, avg(positive) + avg(positive) - avg(negative); example points are not returned. */
export async function recommend(client: Client, args: Search & { field: string; positives: unknown[]; negatives?: unknown[]; metric: string;
  lookup?: string }): Promise<Args[]> {
  const input: Schemas["RecommendInput"] = { positive: args.positives.map(example), strategy: "average_vector" };
  if (args.negatives !== undefined && args.negatives.length > 0) {
    input.negative = args.negatives.map(example);
  }
  const body = { ...request(args), query: { recommend: input }, using: args.field };
  if (args.lookup !== undefined && args.lookup !== args.collection.name) {
    body.lookup_from = { collection: args.lookup, vector: args.field };
  }
  const bound = args.native ? undefined : threshold(args.metric, args.score_min);
  if (bound !== undefined) {
    body.score_threshold = bound;
  }
  const response = await client.qdrant.query(args.collection.name, body);
  return scored(args, args.metric, response.points as Point[]);
}

/** Discovery (with a target) or context search (without); the scores are Qdrant's own, so 'score native' is required. */
export async function discover(client: Client, args: Search & { field: string; context: { positive: unknown; negative: unknown }[];
  target?: unknown }): Promise<Args[]> {
  const pairs = args.context.map((pair) => ({ positive: example(pair.positive), negative: example(pair.negative) }));
  const query: Schemas["QueryInterface"] = args.target === undefined ? { context: pairs } : { discover: { target: example(args.target), context: pairs } };
  const response = await client.qdrant.query(args.collection.name, { ...request(args), query, using: args.field });
  return scored(args, undefined, response.points as Point[]);
}

export async function lookupVector(client: Client, args: { collection: Layout; field: string; id: unknown }): Promise<number[]> {
  const records = await client.qdrant.retrieve(args.collection.name, {
    ids: [pointId(args.id)], with_payload: false, with_vector: [args.field], ...consistency(args.collection),
  });
  if (records.length === 0) {
    throw new Error(`record ${JSON.stringify(args.id)} not found in ${args.collection.name}`);
  }
  return ((records[0].vector as Args)[args.field] as number[]).map(Number);
}

// ---------------------------------------------------------------- schema changes

/** The collection must exist; Qdrant serves every collection and payloads are schemaless, so nothing else is due. */
export async function requireCollection(client: Client, args: { name: string }): Promise<void> {
  if (!(await client.qdrant.collectionExists(args.name)).exists) {
    throw new Error(`collection ${args.name} does not exist`);
  }
}

/** Qdrant's collection update (PATCH /collections/{name}): only the parts given change. */
export async function alterCollection(client: Client, args: { name: string; vectors?: Record<string, Schemas["VectorParamsDiff"]>;
  sparse_vectors?: Record<string, Schemas["SparseVectorParams"]>; hnsw?: Schemas["HnswConfigDiff"]; quantization?: Schemas["QuantizationConfigDiff"];
  optimizers?: Schemas["OptimizersConfigDiff"]; params?: Schemas["CollectionParamsDiff"]; strict_mode?: Schemas["StrictModeConfig"];
  metadata?: Args | null }): Promise<void> {
  const update: Schemas["UpdateCollection"] = {};
  if (args.vectors !== undefined) {
    update.vectors = args.vectors;
  }
  if (args.sparse_vectors !== undefined) {
    update.sparse_vectors = args.sparse_vectors;
  }
  if (args.hnsw !== undefined) {
    update.hnsw_config = args.hnsw;
  }
  if (args.quantization !== undefined) {
    update.quantization_config = args.quantization;
  }
  if (args.optimizers !== undefined) {
    update.optimizers_config = args.optimizers;
  }
  if (args.params !== undefined) {
    update.params = args.params;
  }
  if (args.strict_mode !== undefined) {
    update.strict_mode_config = args.strict_mode;
  }
  if (args.metadata !== undefined) {
    update.metadata = args.metadata;
  }
  await client.qdrant.updateCollection(args.name, update);
}

/** A named vector added to an existing collection (Qdrant 1.20); its index, quantization and memory settings follow as a
 * collection update. Existing points have no value for it. */
export async function createVector(client: Client, args: { name: string; field: string; dense?: Args; sparse?: Args }): Promise<void> {
  const params = args.sparse ?? args.dense ?? {};
  const created = Object.fromEntries(Object.entries(params).filter(([key]) => VECTOR_NAME_KEYS.includes(key)));
  const rest = Object.fromEntries(Object.entries(params).filter(([key]) => !VECTOR_NAME_KEYS.includes(key)));
  const config = (args.sparse === undefined ? { dense: created } : { sparse: created }) as Schemas["VectorNameConfig"];
  await client.qdrant.createVectorName(args.name, args.field, config, { wait: true });
  if (Object.keys(rest).length > 0) {
    await alterCollection(client, args.sparse === undefined
      ? { name: args.name, vectors: { [args.field]: rest } }
      : { name: args.name, sparse_vectors: { [args.field]: rest } });
  }
}

export async function dropVector(client: Client, args: { name: string; field: string }): Promise<void> {
  await client.qdrant.deleteVectorName(args.name, args.field, { wait: true });
}

export async function dropPayloadIndex(client: Client, args: { name: string; field: string }): Promise<void> {
  await client.qdrant.deletePayloadIndex(args.name, args.field, { wait: true });
}

/** Payload indexes of a collection by field: the index schema as JSON. */
async function indexed(client: Client, name: string): Promise<Record<string, Args>> {
  const schema = (await client.qdrant.getCollection(name)).payload_schema ?? {};
  return Object.fromEntries(Object.entries(schema).map(([field, info]) => [field, { type: info!.data_type, ...((info!.params ?? {}) as Args) }]));
}

/** A default for an added field: every point without the field gets the value. */
export async function fillField(client: Client, args: { name: string; field: string; value: unknown }): Promise<void> {
  await client.qdrant.setPayload(args.name, { payload: { [args.field]: args.value }, filter: { must: [{ is_empty: { key: args.field } }] }, wait: true });
}

/** A payload field removed from every point, with its payload index. */
export async function dropField(client: Client, args: { name: string; field: string }): Promise<void> {
  if (args.field in (await indexed(client, args.name))) {
    await dropPayloadIndex(client, args);
  }
  await client.qdrant.deletePayload(args.name, { keys: [args.field], filter: {}, wait: true });
}

/** Qdrant cannot rename a payload key: each point's value is copied to the new key, the old key is removed and its payload
 * index moves to the new key. */
export async function renameField(client: Client, args: { collection: Layout; field: string; new_name: string }): Promise<Args> {
  const name = args.collection.name;
  const index = (await indexed(client, name))[args.field];
  let moved = 0;
  for (const point of await pages(client, args.collection, { must_not: [{ is_empty: { key: args.field } }] }, [args.field], false)) {
    await client.qdrant.setPayload(name, { payload: { [args.new_name]: point.payload?.[args.field] }, points: [point.id], wait: true });
    moved += 1;
  }
  if (index !== undefined) {
    await createPayloadIndex(client, { name, field: args.new_name, schema: index as Schemas["PayloadSchemaParams"] });
    await dropPayloadIndex(client, { name, field: args.field });
  }
  await client.qdrant.deletePayload(name, { keys: [args.field], filter: {}, wait: true });
  return { renamed_count: moved };
}

/** Qdrant cannot rename a named vector: a vector with the same parameters is added under the new name, every point's vector
 * is copied to it, and the old vector is removed. */
export async function renameVector(client: Client, args: { collection: Layout; field: string; new_name: string }): Promise<Args> {
  const name = args.collection.name;
  const params = (await client.qdrant.getCollection(name)).config.params;
  const sparse = args.field in (params.sparse_vectors ?? {});
  const config = (sparse ? (params.sparse_vectors as Args)[args.field] : (params.vectors as Args)[args.field]) as Args;
  await createVector(client, sparse ? { name, field: args.new_name, sparse: config } : { name, field: args.new_name, dense: config });
  let moved = 0;
  for (const point of await pages(client, args.collection, undefined, false, [args.field])) {
    const vector = (point.vector as Args | undefined)?.[args.field];
    if (vector !== undefined && vector !== null) {
      await client.qdrant.updateVectors(name, { points: [{ id: point.id, vector: { [args.new_name]: vector } }], wait: true });
      moved += 1;
    }
  }
  await dropVector(client, { name, field: args.field });
  return { renamed_count: moved };
}

export async function dropAlias(client: Client, args: { alias: string }): Promise<void> {
  await client.qdrant.updateCollectionAliases({ actions: [{ delete_alias: { alias_name: args.alias } }] });
}

export async function createShardKey(client: Client, args: { name: string; shard_key: string }): Promise<void> {
  await client.qdrant.createShardKey(args.name, { shard_key: args.shard_key });
}

export async function dropShardKey(client: Client, args: { name: string; shard_key: string }): Promise<void> {
  await client.qdrant.deleteShardKey(args.name, { shard_key: args.shard_key });
}

export async function hasShardKey(client: Client, args: { name: string; shard_key: string }): Promise<boolean> {
  return ((await client.qdrant.listShardKeys(args.name)).shard_keys ?? []).some((key) => String(key.key) === args.shard_key);
}

/** Qdrant cannot rename a collection: it is cloned under the new name, its aliases move, and the old one is dropped. */
export async function renameCollection(client: Client, args: { name: string; new_name: string }): Promise<void> {
  const aliases = (await client.qdrant.getCollectionAliases(args.name)).aliases.map((alias) => alias.alias_name);
  await cloneCollection(client, { name: args.name, target: args.new_name });
  await dropCollection(client, { name: args.name });
  for (const alias of aliases) {
    await createAlias(client, { alias, collection: args.new_name });
  }
}

// ---------------------------------------------------------------- operational

function queued(info: Schemas["CollectionInfo"]): number {
  return Number(info.update_queue?.length ?? 0);
}

/** No queued updates and no running optimization. */
async function settled(client: Client, name: string): Promise<boolean> {
  const info = await client.qdrant.getCollection(name);
  if (queued(info) > 0) {
    return false;
  }
  return (await client.qdrant.getOptimizations(name)).running.length === 0 && info.status === "green";
}

/** Qdrant acknowledges a write after its WAL entry; this waits until the update queue has applied every write. */
export async function flush(client: Client, args: { name: string }): Promise<void> {
  await poll(async () => queued(await client.qdrant.getCollection(args.name)) === 0, `flush of ${args.name}`);
}

/** Qdrant compacts with its optimizers: an optimizers update (the target segment count, or no change) runs after the current
 * optimizations, and the runtime waits until no optimization runs. */
export async function compact(client: Client, args: { name: string; segments?: number; wait?: boolean }): Promise<void> {
  await alterCollection(client, { name: args.name, optimizers: args.segments === undefined ? {} : { default_segment_number: args.segments } });
  if (args.wait ?? true) {
    await poll(() => settled(client, args.name), `compaction of ${args.name}`);
  }
}

export async function describe(client: Client, args: { name: string; stats?: boolean; index_progress?: boolean }): Promise<Args> {
  const info = await client.qdrant.getCollection(args.name);
  const dense = (info.config.params.vectors ?? {}) as Args;
  const result: Args = {
    name: args.name, status: info.status,
    vectors: "size" in dense ? [""] : Object.keys(dense).sort(),
    sparse_vectors: Object.keys(info.config.params.sparse_vectors ?? {}).sort(),
    payload_schema: Object.fromEntries(Object.entries(info.payload_schema ?? {}).sort(([a], [b]) => compare(a, b))
      .map(([field, schema]) => [field, schema!.data_type])),
    metadata: info.config.metadata ?? {},
  };
  if (args.stats) {
    Object.assign(result, { points_count: info.points_count ?? 0, segments_count: info.segments_count, indexed_vectors_count: info.indexed_vectors_count ?? 0 });
  }
  if (args.index_progress) {
    Object.assign(result, { optimizations_running: (await client.qdrant.getOptimizations(args.name)).running.length, update_queue: queued(info) });
  }
  return value(result) as Args;
}

/** Index states: a payload index is ready once it is in the payload schema (Qdrant builds it before acknowledging); the vector
 * index of a named vector is ready when no update is queued and no optimization runs. */
export async function awaitIndex(client: Client, args: { name: string; field: string; kind: string; state?: string; timeout?: number }): Promise<string> {
  const current = async (): Promise<string> => {
    if (args.kind === "payload") {
      return args.field in (await indexed(client, args.name)) ? "ready" : "pending";
    }
    return (await settled(client, args.name)) ? "ready" : "building";
  };
  if ((args.state ?? "ready") !== "ready") {
    return current();
  }
  return poll(async () => ((await current()) === "ready" ? "ready" : undefined), `index ${args.field} of ${args.name}`, args.timeout ?? WAIT);
}

/** Drops and recreates a payload index with its stored schema. */
export async function rebuildPayloadIndex(client: Client, args: { name: string; field: string }): Promise<void> {
  const schema = (await indexed(client, args.name))[args.field];
  await dropPayloadIndex(client, args);
  await createPayloadIndex(client, { name: args.name, field: args.field, schema: schema as Schemas["PayloadSchemaParams"] });
}

/** Names of collections, aliases, payload indexes, shard keys, tenant values or snapshots, sorted. */
export async function listObjects(client: Client, args: { kind: string; scope?: string; key?: string; prefix?: string; limit?: number }): Promise<string[]> {
  let names: string[];
  if (args.kind === "collections") {
    names = (await client.qdrant.getCollections()).collections.map((collection) => collection.name);
  } else if (args.kind === "aliases") {
    const aliases = args.scope !== undefined ? await client.qdrant.getCollectionAliases(args.scope) : await client.qdrant.getAliases();
    names = aliases.aliases.map((alias) => alias.alias_name);
  } else if (args.kind === "indexes") {
    names = Object.keys(await indexed(client, args.scope!));
  } else if (args.kind === "partitions") {
    names = ((await client.qdrant.listShardKeys(args.scope!)).shard_keys ?? []).map((key) => String(key.key));
  } else if (args.kind === "slices") {
    names = (await client.qdrant.facet(args.scope!, { key: args.key!, limit: 1_000_000, exact: true })).hits.map((hit) => String(hit.value));
  } else if (args.kind === "snapshots") {
    names = Object.keys(await snapshotNames(client, args.scope!));
  } else {
    throw new Error(`cannot list ${args.kind}`);
  }
  names = names.filter((name) => args.prefix === undefined || name.startsWith(args.prefix)).sort(compare);
  return args.limit === undefined ? names : names.slice(0, args.limit);
}

// ---------------------------------------------------------------- snapshots

/** vecDSL snapshot names of a collection and the files Qdrant gave them; Qdrant names snapshots itself, so the runtime keeps
 * the names in the collection metadata. */
async function snapshotNames(client: Client, name: string): Promise<Record<string, string>> {
  const files = new Set((await client.qdrant.listSnapshots(name)).map((snapshot) => snapshot.name));
  const names = (((await client.qdrant.getCollection(name)).config.metadata ?? {}) as Args)[SNAPSHOT_NAMES] as Record<string, string> | undefined;
  return Object.fromEntries(Object.entries(names ?? {}).filter(([, file]) => files.has(file)));
}

async function remember(client: Client, name: string, names: Record<string, string> | null): Promise<void> {
  await client.qdrant.updateCollection(name, { metadata: { [SNAPSHOT_NAMES]: names } });
}

async function recover(client: Client, name: string, location: string, wait: boolean): Promise<void> {
  await client.qdrant.api().recoverFromSnapshot({ collection_name: name, wait, location });
}

export async function createSnapshot(client: Client, args: { name: string; snapshot: string; scope?: string }): Promise<Args> {
  if (args.scope === "full") {
    return { snapshot: args.snapshot, file: (await client.qdrant.createFullSnapshot({ wait: true })).name };
  }
  await flush(client, { name: args.name });
  const file = (await client.qdrant.createSnapshot(args.name, { wait: true }))!.name;
  const names = ((((await client.qdrant.getCollection(args.name)).config.metadata ?? {}) as Args)[SNAPSHOT_NAMES] ?? {}) as Record<string, string>;
  await remember(client, args.name, { ...names, [args.snapshot]: file });
  return { snapshot: args.snapshot, file };
}

async function snapshotSource(client: Client, snapshot: string, source: string | undefined): Promise<string> {
  if (source !== undefined) {
    return source;
  }
  const owners: string[] = [];
  for (const collection of (await client.qdrant.getCollections()).collections) {
    if (snapshot in (await snapshotNames(client, collection.name))) {
      owners.push(collection.name);
    }
  }
  if (owners.length !== 1) {
    throw new Error(`snapshot ${snapshot} belongs to ${owners.length} collections; name the collection`);
  }
  return owners[0];
}

/** Recovery from a snapshot file of the server's snapshots directory, or from a URL. A collection restored from its own
 * snapshot is recovered in place and keeps its snapshot names; any other existing target is replaced (Qdrant recovers into
 * an existing collection only with the snapshot's vector configuration), and its aliases are kept. */
export async function restoreSnapshot(client: Client, args: { name: string; snapshot: string; source?: string; location?: string;
  wait?: boolean }): Promise<Args> {
  const wait = args.wait ?? true;
  let location = args.location;
  let owner: string | undefined;
  let names: Record<string, string> = {};
  if (location === undefined) {
    owner = await snapshotSource(client, args.snapshot, args.source);
    names = await snapshotNames(client, owner);
    location = `file://${SNAPSHOTS}/${owner}/${names[args.snapshot]}`;
  }
  let aliases: string[] = [];
  if (owner !== args.name && (await client.qdrant.collectionExists(args.name)).exists) {
    aliases = (await client.qdrant.getCollectionAliases(args.name)).aliases.map((alias) => alias.alias_name);
    await dropCollection(client, { name: args.name });
  }
  await recover(client, args.name, location, wait);
  for (const alias of aliases) {
    await createAlias(client, { alias, collection: args.name });
  }
  if (wait && owner === args.name) {
    await remember(client, args.name, names);
  }
  return { collection: args.name, count: wait ? await count(client, { collection: { name: args.name } as Layout }) : null };
}

export async function dropSnapshot(client: Client, args: { snapshot: string; source?: string }): Promise<void> {
  const owner = await snapshotSource(client, args.snapshot, args.source);
  const names = await snapshotNames(client, owner);
  await client.qdrant.deleteSnapshot(owner, names[args.snapshot], { wait: true });
  await remember(client, owner, Object.fromEntries(Object.entries(names).filter(([label]) => label !== args.snapshot)));
}

/** A materialized copy: snapshot, recovery under the new name, and removal of the snapshot file. */
export async function cloneCollection(client: Client, args: { name: string; target: string }): Promise<Args> {
  await flush(client, { name: args.name });
  const file = (await client.qdrant.createSnapshot(args.name, { wait: true }))!.name;
  try {
    await recover(client, args.target, `file://${SNAPSHOTS}/${args.name}/${file}`, true);
  } finally {
    await client.qdrant.deleteSnapshot(args.name, file, { wait: true });
  }
  if ((await client.qdrant.getCollection(args.target)).config.metadata) {
    await remember(client, args.target, null);
  }
  return { collection: args.target, count: await count(client, { collection: { name: args.target } as Layout }) };
}

// ---------------------------------------------------------------- import and sampling

/** Records of a local JSON array or JSON Lines file (file:// URI or path). */
export async function readRecords(_client: Client, args: { location: string }): Promise<Args[]> {
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  const text = readFileSync(path, "utf8");
  if (text.trimStart().startsWith("[")) {
    return JSON.parse(text) as Args[];
  }
  return text.split(/\r?\n/).filter((line) => line.trim().length > 0).map((line) => JSON.parse(line) as Args);
}

/** Qdrant has no server-side file import: the runtime reads the file and writes its records in batches. */
export async function importFile(client: Client, args: { collection: Layout; location: string; on_conflict?: string; batch_size?: number;
  wait?: boolean; slice?: Args; shard_key?: ShardKey }): Promise<Args> {
  const rows = await readRecords(client, { location: args.location });
  const common = { collection: args.collection, rows, batch_size: args.batch_size, wait: args.wait ?? true, slice: args.slice, shard_key: args.shard_key };
  if (args.on_conflict === "update" || args.on_conflict === "replace") {
    return upsertRows(client, common);
  }
  return insertRows(client, { ...common, on_conflict: args.on_conflict ?? "error" });
}

/** Qdrant's random sample query, or the first records in primary key order. */
export async function sampleRows(client: Client, args: { collection: Layout; size: number; output: string[]; first?: boolean; filter?: Args;
  shard_key?: ShardKey }): Promise<Args[]> {
  const layout = args.collection;
  if (args.first) {
    return scroll(client, { collection: layout, output: args.output, filter: args.filter, limit: args.size, shard_key: args.shard_key });
  }
  const response = await client.qdrant.query(layout.name, {
    query: { sample: "random" }, filter: filterOf(args.filter), limit: args.size, with_payload: payloadOf(layout, args.output),
    ...consistency(layout), ...shards(args.shard_key),
  });
  return (response.points as Point[]).map((point) => rowOf(layout, point, args.output, undefined))
    .sort((a, b) => compare(a[layout.key], b[layout.key]));
}

/** Qdrant's distance matrix (pairs of a random sample and their nearest neighbours) with primary keys and canonical
 * similarities, sorted by key. */
export async function distanceMatrix(client: Client, args: { collection: Layout; field: string; metric: string; sample?: number; limit?: number;
  filter?: Args; shard_key?: ShardKey }): Promise<Args[]> {
  const layout = args.collection;
  const response = await client.qdrant.searchMatrixPairs(layout.name, {
    filter: filterOf(args.filter), sample: args.sample ?? 10, limit: args.limit ?? 3, using: args.field, ...consistency(layout),
    ...shards(args.shard_key),
  });
  const ids = [...new Set(response.pairs.flatMap((pair) => [String(pair.a), String(pair.b)]))];
  const stored = await client.qdrant.retrieve(layout.name, { ids, with_payload: [layout.key], with_vector: false });
  const keys = new Map(stored.map((point) => [String(point.id), point.payload?.[layout.key]]));
  return response.pairs.map((pair) => ({ a: keys.get(String(pair.a)), b: keys.get(String(pair.b)), score: value(similarity(args.metric, pair.score)) }))
    .sort((x, y) => compare(x.a, y.a) || compare(x.b, y.b));
}
